注意：把"接口地址"移到 API Key 之后、拉取按钮之前，逻辑更顺（先填 key 和 url，再拉取）。

JS 函数设计：

```js
function modelsEndpoint(){
  var c=state.ai.providers[state.ai.provider];
  return (c.url||'').replace(/\/+$/,'')+'/models';
}
function isVisionModel(name){
  return /vision|vl|image|4v|ocr|pixtral|gemini|gpt-4o|mm|multimodal/i.test(name||'');
}
function modelValue(id){
  var m=document.getElementById(id+'Manual');
  if(m && m.style.display!=='none') return m.value.trim();
  return (document.getElementById(id).value||'').trim();
}
function setModelValue(id,val){
  var sel=document.getElementById(id), m=document.getElementById(id+'Manual');
  // 尝试放进 select
  applyModelOptions(id, cachedModels(), val);
  // 如果 val 不在列表里 -> 用手动输入
  var opts=[].map.call(sel.options,function(o){return o.value;});
  if(val && opts.indexOf(val)<0){
    if(m){m.value=val;m.style.display='';sel.style.display='none';updateToggle(id,true);}
  }
}
function cachedModels(){ return state.ai.providers[state.ai.provider].modelList||[]; }
function applyModelOptions(id, models, current){
  var sel=document.getElementById(id);
  if(!sel) return;
  var list=(models||[]).slice();
  if(current && list.indexOf(current)<0) list.unshift(current);
  if(id==='aiVision'){
    list.sort(function(a,b){var va=isVisionModel(a)?0:1,vb=isVisionModel(b)?0:1;return va-vb;});
  }
  sel.innerHTML = list.length
    ? list.map(function(m){return '<option value="'+esc(m)+'"'+(m===current?' selected':'')+'>'+esc(m)+(id==='aiVision'&&isVisionModel(m)?' 👁':'')+'</option>';}).join('')
    : '<option value="">（未拉取，请点上方按钮或手动输入）</option>';
}
```

需要一个 esc 函数（HTML 转义）。原 HTML 里有没有 esc？让我检查。可能叫 escapeHtml 或 esc。要避免重复定义冲突。

我需要查一下有没有 esc 函数。

`toggleModelManual(id)`：
```js
function toggleModelManual(id){
  var sel=document.getElementById(id), m=document.getElementById(id+'Manual');
  var toManual = m.style.display==='none';
  if(toManual){ m.value=sel.value; m.style.display=''; sel.style.display='none'; }
  else { var v=m.value.trim(); applyModelOptions(id, cachedModels(), v||undefined); sel.style.display=''; m.style.display='none'; }
  updateToggle(id,toManual);
}
function updateToggle(id,toManual){var t=document.getElementById(id+'Toggle');if(t)t.textContent=toManual?'改为选择':'手动输入';}
function onModelSelect(id){ /* 用户改了 select，无需特殊处理 */ }
function onUrlChange(){ /* 地址改了清空缓存? 不清也行 */ }
```

`fetchModels(ev)`：
```js
async function fetchModels(ev){
  if(!saveAIConfigSilent()) return;
  var btn=ev&&ev.currentTarget||document.getElementById('fetchBtn');
  var status=document.getElementById('fetchStatus');
  var pr=state.ai.provider, c=state.ai.providers[pr];
  if(pr!=='custom'&&!c.key){toast('请先填 API Key');if(status)status.textContent='请先填 API Key 再拉取';return;}
  if(!c.url){toast('请先填接口地址');return;}
  if(btn){btn.disabled=true;btn.textContent='拉取中…';}
  if(status)status.textContent='正在请求 '+modelsEndpoint()+' …';
  try{
    var res=await fetch(modelsEndpoint(),{method:'GET',headers:{'Authorization':'Bearer '+(c.key||''),'Accept':'application/json'}});
    var txt=await res.text();
    if(!res.ok) throw new Error('HTTP '+res.status+' '+txt.slice(0,160));
    var j;try{j=JSON.parse(txt);}catch(e){throw new Error('返回不是 JSON: '+txt.slice(0,120));}
    var arr = Array.isArray(j)?j:(j.data||j.models||[]);
    var ids=[];
    arr.forEach(function(x){var id = typeof x==='string'?x:(x&&(x.id||x.name));if(id)ids.push(String(id));});
    ids=ids.filter(function(v,i){return ids.indexOf(v)===i;});
    if(!ids.length) throw new Error('接口没返回模型（data 为空）');
    c.modelList=ids;
    save();
    // 填充下拉，尽量保留当前选择
    var curModel=modelValue('aiModel')||ids[0];
    var curVision=modelValue('aiVision')||(ids.filter(isVisionModel)[0]||ids[0]);
    applyModelOptions('aiModel',ids,curModel);
    applyModelOptions('aiVision',ids,curVision);
    c.model=curModel; c.vision=curVision; save();
    if(status)status.textContent='✅ 拉取到 '+ids.length+' 个模型，已在下方列出，请手动选择。';
    toast('拉取成功：'+ids.length+' 个模型');
  }catch(e){
    if(status)status.textContent='❌ 拉取失败：'+(e.message||'未知错误')+'。可点下方「手动输入」自己填模型名。';
    toast('拉取失败：'+(e.message||'未知错误'));
  }finally{ if(btn){btn.disabled=false;btn.textContent='🔄 自动拉取模型列表';} }
}
```

注意 `saveAIConfigSilent()` 原来只读 key/model/url，不读 vision。我要增强它读 vision 和 modelValue。

改造 saveAIConfigSilent：
```js
function saveAIConfigSilent(){
  var pr=document.getElementById('aiProvider').value,c=state.ai.providers[pr];
  c.key=document.getElementById('aiKey').value.trim();
  c.model=modelValue('aiModel');
  c.vision=modelValue('aiVision');
  c.url=document.getElementById('aiUrl').value.trim();
  state.ai.provider=pr;save();return true;
}
```
saveAIConfig 直接调用 saveAIConfigSilent + toast 即可，避免重复：
```js
function saveAIConfig(){ saveAIConfigSilent(); toast('AI 配置已保存'); }
```

renderAIConfig 改造：
```js
function renderAIConfig(){
  var pr=state.ai.provider,c=state.ai.providers[pr]||{};
  document.getElementById('aiProvider').value=pr;
  document.getElementById('aiKey').value=c.key||'';
  document.getElementById('aiUrl').value=c.url||'';
  document.getElementById('urlWrap').style.display=pr==='custom'?'':'none';
  var keyLabel=..., keyHint=...;
  document.getElementById('keyLabel').textContent=keyLabel[pr];
  document.getElementById('keyHint').textContent=keyHint[pr];
  document.getElementById('modelHint').textContent = c.modelList&&c.modelList.length ? '已从接口拉取 '+c.modelList.length+' 个模型，请手动选择' : '点上方「自动拉取模型列表」获取，或手动输入';
  document.getElementById('visionHint').textContent = '识别体测图片用；需支持图片输入';
  document.getElementById('fetchStatus').textContent = c.modelList&&c.modelList.length ? '已缓存上次拉取的 '+c.modelList.length+' 个模型，可重新拉取更新。' : '填好 API Key（自定义接口还需填地址）后点此拉取，再在下方选择。';
  // 重置手动输入显示
  ['aiModel','aiVision'].forEach(function(id){var m=document.getElementById(id+'Manual');if(m){m.style.display='none';m.value='';}var sel=document.getElementById(id);if(sel)sel.style.display='';updateToggle(id,false);});
  applyModelOptions('aiModel',c.modelList||[],c.model||'');
  applyModelOptions('aiVision',c.modelList||[],c.vision||'');
  // 如果当前值不在列表里，自动切到手动输入保留它
  [['aiModel',c.model],['aiVision',c.vision]].forEach(function(p){
    var sel=document.getElementById(p[0]);var found=p[1]&&[].some.call(sel.options,function(o){return o.value===p[1];});
    if(p[1]&&!found){var m=document.getElementById(p[0]+'Manual');m.value=p[1];m.style.display='';sel.style.display='none';updateToggle(p[0],true);}
  });
}
```

还要注意 `esc` 函数。让我先查有没有。

另外，state 里我要不要给 providers 加 modelList 字段？JS 对象是动态的，直接 `c.modelList=ids` 就行，merge/clone 会处理（clone 用 JSON 或递归？看 clone 实现）。如果 clone 用 JSON.parse(JSON.stringify) 那没问题。save 用 JSON.stringify 也没问题。

好，先查 esc 和 clone。

然后修改后要：
1. node --check 校验 JS
2. 重新编译、签名、打包 IPA
3. present_files 展示
4. 更新 memory

